<style scoped lang="scss">
@use '../styles/variables' as *;

.popular-products {
  display: flex;
  flex-direction: column;
  gap: $spacing-4;

  &__header {
    display: flex;
    justify-content: space-between;
    gap: $spacing-4;

    .title {
      white-space: nowrap;
      font-weight: 700;
      font-size: 20px;
    }

    .categories {
      display: flex;
      gap: $spacing-2;

      &__item {
        display: flex;
        align-items: center;
        gap: 6px;
        background: $color-background;
        border-radius: $radius-base;
        padding: 0 $spacing-4;
        font-weight: 700;
        font-size: 13px;
        color: $color-text-muted;

        &.active {
          background: $color-primary;
          color: $color-surface;
        }

        &:hover {
          background: $color-primary-hover;
          color: $color-surface;
        }
      }
    }
  }

  &__content {
    display: flex;
    flex-wrap: wrap;
    gap: $spacing-4;
  }
}
</style>